-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Was ist meine Hauptpflicht als Azubi?', 2, '[{"text": "Lernen", "correct": true, "because": "Ziel der Ausbildung"}, {"text": "Kaffee kochen", "correct": false, "because": "Kein Ausbildungsziel"}, {"text": "Urlaub planen", "correct": false, "because": "Irrelevant"}]'),
