('00000000-0000-0000-0000-000000000000', 'Welches Recht habe ich bei Krankheit?', 2, '[{"text": "Lohnfortzahlung", "correct": true, "because": "Gesetzlich garantiert"}, {"text": "Sofort kündigen", "correct": false, "because": "Kein Recht dazu"}, {"text": "Urlaub verlängern", "correct": false, "because": "Kein Automatismus"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter fragt, was ich tun muss. Was sage ich?', 3, '[{"text": "Berichtsheft führen", "correct": true, "because": "Pflichtaufgabe"}, {"text": "Betrieb dekorieren", "correct": false, "because": "Keine Pflicht"}, {"text": "Chef massieren", "correct": false, "because": "Unsinn"}]'),
