('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ich muss zur Berufsschule gehen. b) Ich kann den Vertrag jederzeit kündigen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schule ja, Kündigung fristgebunden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ich habe Anspruch auf Urlaub. b) Ich muss keine Anweisungen befolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Urlaub ja, Anweisungen ja"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ich darf keine Überstunden machen. b) Ich habe Anspruch auf Vergütung.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Überstunden möglich, Vergütung ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ich muss ein Berichtsheft führen. b) Ich habe kein Recht auf Pausen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Berichtsheft ja, Pausen ja"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

